-- V90.dc: Preventive Maintenance + Machine Reliability
CREATE TABLE IF NOT EXISTS maintenance_plan(plan_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,plan_name TEXT NOT NULL,frequency_type TEXT NOT NULL,frequency_value NUMERIC NOT NULL DEFAULT 1,last_service_date DATE,next_due_date DATE,running_hours_threshold NUMERIC,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS maintenance_order(order_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,plan_id TEXT,order_type TEXT NOT NULL DEFAULT 'PREVENTIVE',status TEXT NOT NULL DEFAULT 'OPEN',scheduled_date DATE,downtime_hours NUMERIC NOT NULL DEFAULT 0,description TEXT,approved_by TEXT,approved_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS maintenance_event(event_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,event_type TEXT NOT NULL,event_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,duration_minutes NUMERIC NOT NULL DEFAULT 0,reason TEXT,maintenance_order_id TEXT,created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_spare_usage(usage_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,work_center_id TEXT NOT NULL,maintenance_order_id TEXT,material_id TEXT NOT NULL,quantity NUMERIC NOT NULL DEFAULT 0,unit_cost NUMERIC NOT NULL DEFAULT 0,total_cost NUMERIC NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_maint_order_scope ON maintenance_order(organization_id,entity_id,work_center_id,scheduled_date,status);
